(361, '_transient_sydney_base_css_a8113a9b4f61b178cd1fea4efa5bf4c8_ltr', 'a:2:{s:3:\"sig\";s:32:\"ec0c8580b55dac8e1c82f13595c57cbe\";s:3:\"css\";s:30006:\"/*SYDNEY_CTX_1*/.woocommerce ul.products li.product { text-align:center;}\n/*SYDNEY_CTX_2*/.header-image { background-size:cover;}\n.header-image { height:300px; }\n/*SYDNEY_CTX_3*/:root {\n  --sydney-global-color-1:#d65050;\n  --sydney-global-color-2:#b73d3d;\n  --sydney-global-color-3:#233452;\n  --sydney-global-color-4:#00102E;\n  --sydney-global-color-5:#6d7685;\n  --sydney-global-color-6:#00102E;\n  --sydney-global-color-7:#F4F5F7;\n  --sydney-global-color-8:#dbdbdb;\n  --sydney-global-color-9:#ffffff;\n}\n.llms-student-dashboard .llms-button-secondary:hover,.llms-button-action:hover,.facts-section.style2 .roll-counter i,.roll-team.type-b.style2 .team-item .team-social li:hover a,.portfolio-section.style2 .project-filter li a:hover,.timeline-section.style2 .timeline .icon .fa::before, .style1 .plan-icon, .style3 .plan-icon, .roll-team.type-b .team-social li a,#mainnav ul li a:hover, .sydney_contact_info_widget span, .roll-team .team-content .name,.roll-team .team-item .team-pop .team-social li:hover a,.roll-infomation li.address:before,.roll-infomation li.phone:before,.roll-infomation li.email:before,.roll-button.border,.roll-button:hover,.roll-icon-list .icon i,.roll-icon-list .content h3 a:hover,.roll-icon-box.white .content h3 a,.roll-icon-box .icon i,.roll-icon-box .content h3 a:hover,.switcher-container .switcher-icon a:focus,.go-top:hover,.hentry .meta-post a:hover,#mainnav > ul > li > a.active, #mainnav > ul > li > a:hover, button:hover, input[type=\"button\"]:hover, input[type=\"reset\"]:hover, input[type=\"submit\"]:hover, .text-color, .social-menu-widget a, .social-menu-widget a:hover, .archive .team-social li a, a, h1 a, h2 a, h3 a, h4 a, h5 a, h6 a, .classic-alt .meta-post a, .single .meta-post a, .header-contact .fa,.social-navigation li a:hover,.widget_sydney_testimonials .fa-quote-left,.timeline-section.style2 .timeline-date, .content-area.modern .hentry .meta-post span:before, .content-area.modern .post-cat,.content-area.modern .read-more-gt { color:var(--sydney-global-color-1)}\n.sydney-post-sharing .sharing-element:hover,.llms-student-dashboard .llms-button-secondary,.llms-button-action,.roll-team.type-b.style2 .avatar::after,.project-filter li a.active, .project-filter li a:hover,.woocommerce a.button,.woocommerce button.button,.woocommerce input.button,.project-filter li.active, .project-filter li:hover,.roll-team.type-b .team-item .team-social li:hover a,.preloader .pre-bounce1, .preloader .pre-bounce2,.roll-team .team-item .team-pop,.roll-progress .progress-animate,.roll-socials li a:hover,.roll-project .project-item .project-pop,.roll-project .project-filter li.active,.roll-project .project-filter li:hover,.roll-button.light:hover,.roll-button.border:hover,.roll-button,.roll-icon-box.white .icon,.owl-theme .owl-controls .owl-page.active span,.owl-theme .owl-controls.clickable .owl-page:hover span,.go-top,.bottom .socials li:hover a,.sidebar .widget:before,.blog-pagination ul li.active,.blog-pagination ul li:hover a,.content-area .hentry:after,.text-slider .maintitle:after,.error-wrap #search-submit:hover,#mainnav .sub-menu li:hover > a,#mainnav ul li ul:after, button, input[type=\"button\"], input[type=\"reset\"], input[type=\"submit\"], .panel-grid-cell .widget-title:after, .social-section.style2 .social-menu-widget li a:hover, .count-number, .cart-amount, .sydney-video.vid-lightbox .toggle-popup,.footer-contact .widget-title:after,.fp-contact .fa,.pricing-section.style4 .plan-item.featured-plan .plan-header, .woocommerce .widget_price_filter .ui-slider .ui-slider-range { background-color:var(--sydney-global-color-1)}\n.llms-student-dashboard .llms-button-secondary,.llms-student-dashboard .llms-button-secondary:hover,.llms-button-action,.llms-button-action:hover,.owl-theme .owl-controls .owl-page:hover span,.owl-theme .owl-controls .owl-page.acti